import android.widget.*;

import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.auth.FirebaseUser;
import com.google.firebase.firestore.DocumentSnapshot;
import com.google.firebase.firestore.FieldValue;
import com.google.firebase.firestore.FirebaseFirestore;
import com.google.firebase.firestore.Query;
import com.google.firebase.firestore.SetOptions;
import com.google.firebase.functions.FirebaseFunctions;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Best Nikah Bridge production launcher.
 * Real Firebase-backed account, profile, matching, consent, family, safety,
 * verification, privacy, mutual-only communication and account deletion.
 * No demo members, fake scores, fake badges or local-only connection state.
 */
public class MainActivity extends Activity {
    private FirebaseAuth auth;
    private FirebaseFirestore db;
    private FirebaseFunctions functions;
    private LinearLayout root;
    private final int green=Color.rgb(18,103,82), dark=Color.rgb(30,45,41), gray=Color.rgb(95,108,103), red=Color.rgb(165,50,50), light=Color.rgb(247,250,249);

    @Override protected void onCreate(Bundle state){super.onCreate(state);auth=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();functions=FirebaseFunctions.getInstance();route();}
    @Override public void onBackPressed(){if(auth.getCurrentUser()==null)authScreen();else home();}

    private void route(){FirebaseUser u=auth.getCurrentUser();if(u==null){authScreen();return;}if(!u.isEmailVerified()){verificationGate();return;}db.collection("users").document(u.getUid()).get().addOnSuccessListener(d->{if(!d.exists()||!Boolean.TRUE.equals(d.getBoolean("profileActive")))profile();else home();}).addOnFailureListener(e->toast("Secure profile check failed. Please try again."));}
    private void base(){ScrollView s=new ScrollView(this);s.setFillViewport(true);s.setBackgroundColor(light);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(22,24,22,32);s.addView(root);setContentView(s);}
    private TextView text(String v,int size,boolean bold){TextView t=new TextView(this);t.setText(v);t.setTextSize(size);t.setTextColor(bold?dark:gray);t.setPadding(6,8,6,12);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
    private void title(String v){TextView t=text(v,28,true);t.setGravity(Gravity.CENTER);root.addView(t);}
    private Button button(String label,boolean filled){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(16);b.setTextColor(filled?Color.WHITE:green);GradientDrawable g=new GradientDrawable();g.setColor(filled?green:Color.WHITE);g.setCornerRadius(18);if(!filled)g.setStroke(2,green);b.setBackground(g);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,62);p.setMargins(0,6,0,6);root.addView(b,p);return b;}
    private Button danger(String label){Button b=button(label,false);b.setTextColor(red);GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(18);g.setStroke(2,red);b.setBackground(g);return b;}
    private EditText input(String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextSize(16);e.setPadding(14,8,14,8);root.addView(e,new LinearLayout.LayoutParams(-1,62));return e;}
    private void section(String v){root.addView(text(v,19,true));}
    private void toast(String v){Toast.makeText(this,v,Toast.LENGTH_LONG).show();}
    private String val(DocumentSnapshot d,String key){Object v=d.get(key);return v==null?"":String.valueOf(v);}
    private boolean signedIn(){return auth.getCurrentUser()!=null;}

    private void authScreen(){base();title("Best Nikah Bridge");root.addView(text("Real Firebase account • Serious Nikah only • Not a dating app",16,false));EditText email=input("Email address");email.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);EditText password=input("Password (minimum 8 characters)");password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);Button sign=button("Sign in",true),create=button("Create account",false),terms=button("Terms & Community Rules",false);sign.setOnClickListener(v->{if(!valid(email,password))return;auth.signInWithEmailAndPassword(email.getText().toString().trim(),password.getText().toString()).addOnSuccessListener(x->route()).addOnFailureListener(e->toast("Sign in failed. Check your email and password."));});create.setOnClickListener(v->{if(!valid(email,password))return;auth.createUserWithEmailAndPassword(email.getText().toString().trim(),password.getText().toString()).addOnSuccessListener(x->{FirebaseUser u=x.getUser();if(u==null)return;u.sendEmailVerification();Map<String,Object> p=new HashMap<>();p.put("uid",u.getUid());p.put("profileActive",false);p.put("verificationStatus","unverified");p.put("termsAccepted",false);p.put("createdAt",FieldValue.serverTimestamp());db.collection("users").document(u.getUid()).set(p).addOnSuccessListener(y->verificationGate()).addOnFailureListener(e->toast("Account setup failed."));}).addOnFailureListener(e->toast("Account creation failed. Email may already be registered."));});terms.setOnClickListener(v->terms());}
    private boolean valid(EditText e,EditText p){if(!e.getText().toString().trim().contains("@")){e.setError("Valid email required");return false;}if(p.getText().toString().length()<8){p.setError("Minimum 8 characters");return false;}return true;}
    private void verificationGate(){base();title("Verify your email");root.addView(text("Email verification is required before your profile can become active.",16,false));Button resend=button("Resend verification email",true),refresh=button("I verified — continue",false),out=button("Sign out",false);resend.setOnClickListener(v->{FirebaseUser u=auth.getCurrentUser();if(u!=null)u.sendEmailVerification().addOnSuccessListener(x->toast("Verification email sent."));});refresh.setOnClickListener(v->{FirebaseUser u=auth.getCurrentUser();if(u==null){authScreen();return;}u.reload().addOnSuccessListener(x->{if(u.isEmailVerified())route();else toast("Email is not verified yet.");});});out.setOnClickListener(v->{auth.signOut();authScreen();});}

    private void home(){base();title("Best Nikah Bridge");root.addView(text("Halal Muslim matrimonial platform — built for serious marriage, privacy and family involvement.",17,false));Button p=button("My Profile & Intent",true),r=button("Nikah Readiness Score",true),m=button("Compatibility Matches",true),i=button("Mutual Interests & Safe Chat",true),w=button("Family / Wali Connect",true),s=button("Scam Shield & Safety",false),v=button("Real Verification",false),h=button("Nikah Assistant / Help",false),pr=button("Privacy Control Center",false),a=button("Delete Account / Sign out",false);p.setOnClickListener(x->profile());r.setOnClickListener(x->readiness());m.setOnClickListener(x->matches());i.setOnClickListener(x->interests());w.setOnClickListener(x->wali());s.setOnClickListener(x->safety());v.setOnClickListener(x->verification());h.setOnClickListener(x->help());pr.setOnClickListener(x->privacy());a.setOnClickListener(x->account());root.addView(text("Only real Firebase data is used. No demo members or fake match records are generated.",14,false));}

    private void profile(){base();title("My Real Nikah Profile");root.addView(text("Your profile is discoverable only after email verification, required fields and Terms acceptance. Be truthful and respectful.",15,false));EditText name=input("Full name"),age=input("Age (18+)"),country=input("Country"),city=input("City"),gender=input("Gender"),marital=input("Marital status"),intent=input("Marriage intention"),practice=input("Religious practice"),about=input("About yourself and family values (30+ characters)"),pref=input("Partner preferences (age, location, values, education, etc.)"),timeline=input("Marriage timeline"),family=input("Family / Wali preference"),deal=input("Compatibility deal-breakers / non-negotiables");CheckBox accepted=new CheckBox(this);accepted.setText("I accept the Terms & Community Rules and confirm this is a genuine marriage intention.");root.addView(accepted);Button save=button("Save & Activate Profile",true),verify=button("Request Verification",false),back=button("Back",false);db.collection("users").document(auth.getUid()).get().addOnSuccessListener(d->{name.setText(val(d,"name"));age.setText(val(d,"age"));country.setText(val(d,"country"));city.setText(val(d,"city"));gender.setText(val(d,"gender"));marital.setText(val(d,"maritalStatus"));intent.setText(val(d,"marriageIntent"));practice.setText(val(d,"religiousPractice"));about.setText(val(d,"about"));pref.setText(val(d,"partnerPreference"));timeline.setText(val(d,"marriageTimeline"));family.setText(val(d,"familyInvolvement"));deal.setText(val(d,"dealbreakers"));accepted.setChecked(Boolean.TRUE.equals(d.getBoolean("termsAccepted")));root.addView(text("Verification: "+val(d,"verificationStatus"),15,false));});save.setOnClickListener(v->{int a;try{a=Integer.parseInt(age.getText().toString().trim());}catch(Exception e){age.setError("Enter age");return;}if(a<18||a>100){age.setError("Age must be 18–100");return;}String n=name.getText().toString().trim(),c=country.getText().toString().trim(),ci=city.getText().toString().trim(),g=gender.getText().toString().trim(),ms=marital.getText().toString().trim(),in=intent.getText().toString().trim(),rp=practice.getText().toString().trim(),ab=about.getText().toString().trim(),pp=pref.getText().toString().trim(),tl=timeline.getText().toString().trim(),fa=family.getText().toString().trim(),dbk=deal.getText().toString().trim();if(n.length()<2||c.isEmpty()||ci.isEmpty()||g.isEmpty()||ms.isEmpty()||in.isEmpty()||rp.isEmpty()||ab.length()<30||pp.length()<10||tl.isEmpty()||fa.isEmpty()||dbk.length()<5){toast("Complete every required profile field.");return;}if(!accepted.isChecked()){toast("Accept the Terms and confirm genuine marriage intention first.");return;}Map<String,Object> q=new HashMap<>();q.put("uid",auth.getUid());q.put("name",n);q.put("age",a);q.put("country",c);q.put("city",ci);q.put("gender",g);q.put("maritalStatus",ms);q.put("marriageIntent",in);q.put("religiousPractice",rp);q.put("about",ab);q.put("partnerPreference",pp);q.put("marriageTimeline",tl);q.put("familyInvolvement",fa);q.put("dealbreakers",dbk);q.put("termsAccepted",true);q.put("intentConfirmed",true);q.put("profileActive",true);q.put("updatedAt",FieldValue.serverTimestamp());db.collection("users").document(auth.getUid()).set(q,SetOptions.merge()).addOnSuccessListener(x->{toast("Real profile activated securely.");home();}).addOnFailureListener(e->toast("Profile could not be saved."));});verify.setOnClickListener(v->verification());back.setOnClickListener(v->home());}

    private void readiness(){base();title("Nikah Readiness Score");root.addView(text("Transparent preparation aid — not a religious ruling and not a guarantee of compatibility.",15,false));db.collection("users").document(auth.getUid()).get().addOnSuccessListener(d->{int score=0;String[] keys={"name","country","city","about","partnerPreference","marriageIntent","marriageTimeline","familyInvolvement","dealbreakers"};for(String k:keys)if(!val(d,k).trim().isEmpty())score+=9;if(d.getLong("age")!=null)score+=9;if(Boolean.TRUE.equals(d.getBoolean("termsAccepted")))score+=5;if(Boolean.TRUE.equals(d.getBoolean("intentConfirmed")))score+=5;if("verified".equalsIgnoreCase(val(d,"verificationStatus")))score+=10;if(score>100)score=100;root.addView(text("Nikah Readiness: "+score+" / 100",27,true));root.addView(text(score>=85?"Strong preparation. Focus on family discussion and real-world compatibility.":score>=65?"Good foundation. Complete the missing areas before moving quickly.":"Build your profile, clarify boundaries, timeline and family involvement first.",17,false));});Button b=button("Back",false);b.setOnClickListener(v->home());}

    private void matches(){base();title("Compatibility Matches");root.addView(text("Matches are calculated from real profile fields. No hard-coded fake percentage and no demo profiles.",15,false));db.collection("users").document(auth.getUid()).get().addOnSuccessListener(me->{db.collection("users").whereEqualTo("profileActive",true).limit(100).get().addOnSuccessListener(q->{boolean any=false;for(DocumentSnapshot d:q){if(auth.getUid().equals(d.getId()))continue;any=true;addMatch(me,d);}if(!any)root.addView(text("No real active profiles are available yet. This is normal for a new community.",16,false));}).addOnFailureListener(e->toast("Could not load real matches."));}).addOnFailureListener(e->toast("Could not load your profile."));Button b=button("Back",false);b.setOnClickListener(v->home());}
    private int score(DocumentSnapshot me,DocumentSnapshot d){int s=0;String myIntent=val(me,"marriageIntent"),myTimeline=val(me,"marriageTimeline"),myCountry=val(me,"country"),myGender=val(me,"gender"),theirGender=val(d,"gender"),myPref=val(me,"partnerPreference").toLowerCase(Locale.US),theirCity=val(d,"city").toLowerCase(Locale.US),theirCountry=val(d,"country").toLowerCase(Locale.US),theirIntent=val(d,"marriageIntent"),theirTimeline=val(d,"marriageTimeline");if(!myIntent.isEmpty()&&myIntent.equalsIgnoreCase(theirIntent))s+=25;if(!myTimeline.isEmpty()&&myTimeline.equalsIgnoreCase(theirTimeline))s+=20;if(!myCountry.isEmpty()&&myCountry.equalsIgnoreCase(theirCountry))s+=15;if(!myPref.isEmpty()&&((!theirCity.isEmpty()&&myPref.contains(theirCity))||(!theirCountry.isEmpty()&&myPref.contains(theirCountry))))s+=15;if(!myGender.isEmpty()&&!theirGender.isEmpty()&&!myGender.equalsIgnoreCase(theirGender))s+=10;if("verified".equalsIgnoreCase(val(d,"verificationStatus")))s+=10;if(Boolean.TRUE.equals(d.getBoolean("intentConfirmed")))s+=5;return Math.min(100,s);}
    private void addMatch(DocumentSnapshot me,DocumentSnapshot d){String n=val(d,"name");if(n.isEmpty())n="Member";int s=score(me,d);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(12,10,12,10);root.addView(card);card.addView(text(n+" • "+val(d,"age"),20,true));card.addView(text("Location: "+val(d,"city")+", "+val(d,"country")+"\nMarriage: "+val(d,"marriageIntent")+"\nTimeline: "+val(d,"marriageTimeline")+"\nVerification: "+val(d,"verificationStatus")+"\nCompatibility: "+s+"%",15,false));card.addView(text("Why we matched: intent + timeline + location/preferences + trust signals.",14,false));Button view=button("View Profile",true),interest=button("Express Interest",false),report=danger("Report User");card.addView(view);card.addView(interest);card.addView(report);view.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(n).setMessage("Age: "+val(d,"age")+"\nLocation: "+val(d,"city")+", "+val(d,"country")+"\nMarriage intention: "+val(d,"marriageIntent")+"\nTimeline: "+val(d,"marriageTimeline")+"\nFamily/Wali: "+val(d,"familyInvolvement")+"\nVerification: "+val(d,"verificationStatus")+"\n\nAbout:\n"+val(d,"about")+"\n\nSafety: never send money, OTPs, passwords or unnecessary identity documents.").setPositiveButton("Close",null).show());interest.setOnClickListener(v->sendInterest(d.getId(),interest));report.setOnClickListener(v->reportDialog(d.getId()));}
    private void sendInterest(String uid,Button b){if(!signedIn())return;b.setEnabled(false);Map<String,Object> m=new HashMap<>();m.put("toUid",uid);functions.getHttpsCallable("sendInterest").call(m).addOnSuccessListener(x->{b.setText("Interest Sent ✓");toast("Interest sent. Chat remains locked until mutual acceptance.");}).addOnFailureListener(e->{b.setEnabled(true);toast("Interest could not be sent. It may already exist or the profile changed.");});}

    private void interests(){base();title("Mutual Interests & Safe Chat");root.addView(text("Only mutual acceptance unlocks communication. The backend remains authoritative.",15,false));String me=auth.getUid();section("Incoming Interests");db.collection("interests").whereEqualTo("toUid",me).whereEqualTo("status","pending").get().addOnSuccessListener(q->{if(q.isEmpty())root.addView(text("No pending interests.",15,false));for(DocumentSnapshot d:q){String id=d.getId(),from=val(d,"fromUid");Button a=button("Accept • "+from,true),r=button("Decline • "+from,false);a.setOnClickListener(v->respond(id,"accepted"));r.setOnClickListener(v->respond(id,"declined"));}});section("Active Mutual Connections");loadConnections(me);Button b=button("Back",false);b.setOnClickListener(v->home());}
    private void respond(String id,String decision){Map<String,Object> m=new HashMap<>();m.put("interestId",id);m.put("decision",decision);functions.getHttpsCallable("respondToInterest").call(m).addOnSuccessListener(x->{toast("Interest updated securely.");interests();}).addOnFailureListener(e->toast("Could not update the interest."));}
    private void loadConnections(String me){db.collection("connections").whereEqualTo("uid1",me).whereEqualTo("status","active").get().addOnSuccessListener(q->addConnections(q,me));db.collection("connections").whereEqualTo("uid2",me).whereEqualTo("status","active").get().addOnSuccessListener(q->addConnections(q,me));}
    private void addConnections(com.google.firebase.firestore.QuerySnapshot q,String me){for(DocumentSnapshot d:q){String other=me.equals(val(d,"uid1"))?val(d,"uid2"):val(d,"uid1");if(!other.isEmpty()){Button c=button("Safe Chat • "+other,true);c.setOnClickListener(v->chat(d.getId(),other));}}}
    private void chat(String cid,String other){base();title("Safe Chat");root.addView(text("Mutual connection only. Never send money, OTPs, passwords or private identity documents.",15,false));LinearLayout messages=new LinearLayout(this);messages.setOrientation(LinearLayout.VERTICAL);root.addView(messages);db.collection("connections").document(cid).collection("messages").orderBy("sentAt",Query.Direction.ASCENDING).limitToLast(100).get().addOnSuccessListener(q->{for(DocumentSnapshot d:q)messages.addView(text((auth.getUid().equals(val(d,"fromUid"))?"You: ":"Them: ")+val(d,"text"),15,false));});EditText e=input("Respectful message (1–4000 chars)");Button send=button("Send Message",true),report=danger("Report User"),block=danger("Block User"),back=button("Back",false);send.setOnClickListener(v->{String t=e.getText().toString().trim();if(t.isEmpty()||t.length()>4000){toast("Message must be 1–4000 characters.");return;}Map<String,Object> m=new HashMap<>();m.put("fromUid",auth.getUid());m.put("toUid",other);m.put("text",t);m.put("sentAt",FieldValue.serverTimestamp());db.collection("connections").document(cid).collection("messages").add(m).addOnSuccessListener(x->{e.setText("");messages.addView(text("You: "+t,15,false));}).addOnFailureListener(x->toast("Message blocked by secure rules."));});report.setOnClickListener(v->reportDialog(other));block.setOnClickListener(v->blockUser(other));back.setOnClickListener(v->interests());}
    private void reportDialog(String uid){String[] reasons={"Suspicious profile","Harassment","Spam / scam","Inappropriate content","Safety concern"};new AlertDialog.Builder(this).setTitle("Report user").setItems(reasons,(d,w)->{Map<String,Object> m=new HashMap<>();m.put("reporterUid",auth.getUid());m.put("reportedUid",uid);m.put("reason",reasons[w]);m.put("status","pending");m.put("createdAt",FieldValue.serverTimestamp());db.collection("reports").add(m).addOnSuccessListener(x->toast("Report submitted to moderation.")).addOnFailureListener(x->toast("Report failed."));}).setNegativeButton("Cancel",null).show();}
    private void blockUser(String uid){Map<String,Object> m=new HashMap<>();m.put("blockedUid",uid);functions.getHttpsCallable("blockUser").call(m).addOnSuccessListener(x->{toast("User blocked securely.");interests();}).addOnFailureListener(e->toast("Could not block this user."));}

    private void wali(){base();title("Family / Wali Connect");root.addView(text("Consent-based family participation. The Wali must have a Best Nikah Bridge account. Never share passwords or private credentials.",15,false));EditText uid=input("Trusted Wali account UID");Button req=button("Request Wali Connection",true),back=button("Back",false);req.setOnClickListener(v->{String w=uid.getText().toString().trim();if(w.isEmpty()||w.equals(auth.getUid())){toast("Enter a valid Wali account UID.");return;}Map<String,Object> m=new HashMap<>();m.put("waliUid",w);functions.getHttpsCallable("requestWaliConnection").call(m).addOnSuccessListener(x->toast("Wali request sent securely.")).addOnFailureListener(e->toast("Wali request failed."));});back.setOnClickListener(v->home());}
    private void safety(){base();title("Scam Shield & Safety");root.addView(text("• Never send money or accept financial requests.\n\n• Never share OTPs, passwords, bank details or recovery codes.\n\n• Do not upload unnecessary identity documents to chats.\n\n• Verification is a trust signal, not a guarantee.\n\n• Keep communication inside the app until trust is established.\n\n• Report and block suspicious behavior immediately.\n\n• Involve family/Wali when appropriate.\n\n• For threats or emergencies, contact local authorities.\n\n• Religious rulings should come from qualified scholars.",17,false));Button b=button("Back",false);b.setOnClickListener(v->home());}
    private void verification(){base();title("Real Verification");root.addView(text("Verification requests are stored in Firebase. Only authorized moderation can mark a member verified.",15,false));db.collection("users").document(auth.getUid()).get().addOnSuccessListener(d->root.addView(text("Current status: "+val(d,"verificationStatus"),18,true)));EditText note=input("Optional note — do not enter ID numbers or sensitive documents here");Button submit=button("Submit Verification Request",true),back=button("Back",false);submit.setOnClickListener(v->{Map<String,Object> m=new HashMap<>();m.put("userUid",auth.getUid());m.put("note",note.getText().toString().trim());m.put("status","pending");m.put("createdAt",FieldValue.serverTimestamp());db.collection("verifications").add(m).addOnSuccessListener(x->toast("Verification request submitted.")).addOnFailureListener(x->toast("Verification request failed."));});back.setOnClickListener(v->home());}

    private void help(){base();title("Nikah Assistant");root.addView(text("Real preparation assistant: use these prompts to discuss compatibility respectfully. This is not a fake AI chat and does not issue religious rulings.",16,false));EditText q=input("Ask about compatibility, family, timeline, boundaries or safety");Button ask=button("Get Structured Guidance",true),back=button("Back",false);ask.setOnClickListener(v->{String x=q.getText().toString().trim().toLowerCase(Locale.US);if(x.isEmpty()){toast("Write a question first.");return;}String answer;if(x.contains("family")||x.contains("wali"))answer="Discuss Wali/family involvement early, agree who should participate, and keep consent clear for both sides.";else if(x.contains("money")||x.contains("finance"))answer="Discuss financial expectations, responsibilities, debt, housing and work honestly before commitment. Never send money to an online match.";else if(x.contains("timeline")||x.contains("when")||x.contains("marriage"))answer="Compare intended marriage timeline, readiness, relocation needs and family expectations. Do not rush because of pressure.";else if(x.contains("red flag")||x.contains("scam")||x.contains("safe"))answer="Never share OTPs, passwords or money. Report pressure, inconsistent identity, urgent financial requests or abusive behavior.";else answer="Ask about deen and values, character, family expectations, location, children, finances, conflict resolution, boundaries and realistic marriage timing.";new AlertDialog.Builder(this).setTitle("Nikah Guidance").setMessage(answer+"\n\nFor religious/fiqh questions, consult a qualified scholar.").setPositiveButton("Close",null).show();});back.setOnClickListener(v->home());}

    private void privacy(){base();title("Privacy Control Center");root.addView(text("Only collect and share information needed for matrimonial matching, safety and account operation. Contact details should remain private.",16,false));CheckBox discovery=new CheckBox(this);discovery.setText("Allow my active profile to appear in matching");CheckBox wali=new CheckBox(this);wali.setText("Allow family/Wali connection requests");CheckBox safety=new CheckBox(this);safety.setText("Allow safety/moderation processing of reports and verification");root.addView(discovery);root.addView(wali);root.addView(safety);db.collection("users").document(auth.getUid()).collection("settings").document("privacy").get().addOnSuccessListener(d->{discovery.setChecked(!d.exists()||!Boolean.FALSE.equals(d.getBoolean("discoverable")));wali.setChecked(!d.exists()||!Boolean.FALSE.equals(d.getBoolean("waliRequests")));safety.setChecked(!d.exists()||!Boolean.FALSE.equals(d.getBoolean("safetyProcessing")));});Button save=button("Save Privacy Controls",true),back=button("Back",false);save.setOnClickListener(v->{Map<String,Object> p=new HashMap<>();p.put("discoverable",discovery.isChecked());p.put("waliRequests",wali.isChecked());p.put("safetyProcessing",safety.isChecked());p.put("updatedAt",FieldValue.serverTimestamp());db.collection("users").document(auth.getUid()).collection("settings").document("privacy").set(p,SetOptions.merge()).addOnSuccessListener(x->toast("Privacy controls saved.")).addOnFailureListener(x->toast("Privacy controls could not be saved."));});back.setOnClickListener(v->home());}
    private void account(){base();title("Account & Deletion");root.addView(text("Account deletion is permanent and is handled by the trusted Firebase backend. Some records may be retained when legally necessary for safety or compliance.",16,false));Button del=danger("Permanently Delete Account"),out=button("Sign out",false),back=button("Back",false);del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Delete account?").setMessage("This cannot be undone.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->deleteAccount()).show());out.setOnClickListener(v->{auth.signOut();authScreen();});back.setOnClickListener(v->home());}
    private void deleteAccount(){functions.getHttpsCallable("deleteMyAccount").call(new HashMap<>()).addOnSuccessListener(x->{auth.signOut();toast("Account deleted.");authScreen();}).addOnFailureListener(e->toast("Deletion failed. Sign in again and retry."));}
    private void terms(){base();title("Terms & Community Rules");root.addView(text("Best Nikah Bridge is for serious Muslim matrimonial intent, not casual dating. Users must provide truthful information, respect consent and boundaries, and avoid harassment, scams, impersonation, threats, abusive content and requests for money. Do not exchange passwords, OTPs or unnecessary identity documents. Reports and moderation are used for safety. Verification is not a guarantee of character or marriage outcome. Religious guidance should be obtained from qualified scholars.",16,false));Button b=button("Back",false);b.setOnClickListener(v->home());}
}
